import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第四册：流利英语 · Lesson 22 Knowledge and progress","description":"学习 what 从句作主语与表语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 22 Knowledge and progress","description":"学习 what 从句作主语与表语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 what 从句作主语与表语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 21 William S. Hart and the early 'Western' film","link":"/life/english/new-concept/book-4/unit-03/lesson-021"},"next":{"text":"第四册：流利英语 · Lesson 23 Bird flight","link":"/life/english/new-concept/book-4/unit-03/lesson-023"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 21 William S. Hart and the early 'Western' film","link":"/life/english/new-concept/book-4/unit-03/lesson-021"},"next":{"text":"第四册：流利英语 · Lesson 23 Bird flight","link":"/life/english/new-concept/book-4/unit-03/lesson-023"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-03/lesson-022.md","filePath":"life/english/new-concept/book-4/unit-03/lesson-022.md"}`),r={name:"life/english/new-concept/book-4/unit-03/lesson-022.md"};function s(l,e,i,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-22-knowledge-and-progress" tabindex="-1">第四册：流利英语 · Lesson 22 Knowledge and progress <a class="header-anchor" href="#第四册-流利英语-·-lesson-22-knowledge-and-progress" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 22 Knowledge and progress&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕知识增长与社会进步的关系练习论证阅读。区分“知道更多”“有能力做更多”和“做得更好”这三种命题，识别作者是否省略了从技术能力到价值判断的推理。输出一段有明确标准的评论，用例子说明知识的用途如何影响进步判断。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>knowledge</td><td>/ˈnɒlɪdʒ/</td><td>n.</td><td>知识</td><td>apply knowledge</td></tr><tr><td>progress</td><td>/ˈprəʊɡres/</td><td>n.</td><td>进步</td><td>measure progress</td></tr><tr><td>criterion</td><td>/kraɪˈtɪəriən/</td><td>n.</td><td>标准</td><td>a clear criterion</td></tr><tr><td>consequence</td><td>/ˈkɒnsɪkwəns/</td><td>n.</td><td>后果</td><td>an unintended consequence</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>put into practice — 付诸实践</li><li>for the benefit of — 为了某人的利益</li></ul><h2 id="语法讲解-what-从句作主语与表语" tabindex="-1">语法讲解：what 从句作主语与表语 <a class="header-anchor" href="#语法讲解-what-从句作主语与表语" aria-label="Permalink to &quot;语法讲解：what 从句作主语与表语&quot;">​</a></h2><p>what 从句相当于 the thing(s) that，内部的 what 同时承担从句成分。What matters is how the knowledge is used. 中 what 作 matters 的主语，整个从句作主句主语。that 内容从句中的 that 通常不充当从句成分，因此不可随意互换。what 从句作主语时谓语往往用单数；若语义明确指多个事物，实际一致关系需看整体结构，初学写作宜使用清晰单数表达。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>What matters is whether the new tool solves a real problem.</p></blockquote><p>重要的是新工具是否解决了一个真实问题。</p><p>What matters 为主语从句；whether…problem 为表语从句，说明评判内容。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>That matters is… 不能替代 What matters is…；what 在从句中还承担 matters 的主语。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>在 What matters 后轻停，在 whether 后保持陈述式节奏；重读 real problem，突出评价标准。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>What matters is whether students understand more. Faster completion alone does not prove deeper learning. We could compare how well students explain a new problem after using the tool.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句评价一款虚构学习工具，给出一个进步标准和一个验证方法。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>先定标准，再排除替代指标，最后提出能对应标准的验证方式。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中主句的系动词是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 前后两个从句由 is 连接。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：___ we need is a clearer measure of success.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> What</p><p><strong>解析：</strong> what 作 need 的宾语，整个从句作主句主语。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将 What matters 改为含 thing 的同义表达。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The thing that matters</p><p><strong>解析：</strong> what 从句具有融合关系结构的意义。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：what 从句作主语与表语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-021">上一课</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-03/lesson-023">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
